package main

import (
	"context"
	"errors"
	"reflect"
	"runtime"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/scan"
)

// scanFlightOutcome is one run()'s outcome delivered over a channel, so tests
// can await a goroutine's run call with a timeout instead of hanging forever
// on a regression.
type scanFlightOutcome struct {
	result scan.Result
	err    error
}

// awaitOutcome receives one outcome or fails the test on a timeout.
func awaitOutcome(t *testing.T, ch <-chan scanFlightOutcome, what string) (scan.Result, error) {
	t.Helper()
	select {
	case o := <-ch:
		return o.result, o.err
	case <-time.After(5 * time.Second):
		t.Fatalf("%s: timed out waiting for run to return", what)
		return scan.Result{}, nil
	}
}

// awaitSignal receives one struct{} (a closed start/ready channel) or fails.
func awaitSignal(t *testing.T, ch <-chan struct{}, what string) {
	t.Helper()
	select {
	case <-ch:
	case <-time.After(5 * time.Second):
		t.Fatalf("%s: timed out", what)
	}
}

// gateFn returns an fn whose first execution records the call, signals started
// (exactly once), then blocks on gate — the "slow scan" every join test
// suspends the starter in. A second execution (a joiner that failed to join)
// bumps calls past 1, which the tests assert against.
func gateFn(gate, started chan struct{}, calls *atomic.Int32, result scan.Result, err error) func(context.Context, int64) (scan.Result, error) {
	var once sync.Once
	return func(_ context.Context, _ int64) (scan.Result, error) {
		calls.Add(1)
		once.Do(func() { close(started) })
		<-gate
		return result, err
	}
}

// launchRun dispatches one run call on its own goroutine, delivering its
// outcome to ch.
func launchRun(f *scanFlight, libraryID int64, fn func(context.Context, int64) (scan.Result, error), ch chan<- scanFlightOutcome) {
	go func() {
		res, err := f.run(context.Background(), libraryID, fn)
		ch <- scanFlightOutcome{result: res, err: err}
	}()
}

// waitParked polls the runtime goroutine dump until some goroutine is parked
// in a select INSIDE scanFlight.run — airtight, condition-based proof that a
// joiner has looked up the in-flight entry and committed to the wait path
// (where it can only receive the recorded outcome, never start a second fn
// execution). The starter never matches: while the gate is closed it is
// parked in [chan receive] inside fn, not [select] in run. Fixed sleeps would
// guess at scheduling; this condition cannot be satisfied early.
func waitParked(t *testing.T) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	buf := make([]byte, 1<<20)
	for {
		n := runtime.Stack(buf, true)
		for _, stack := range strings.Split(string(buf[:n]), "\n\n") {
			if strings.Contains(stack, "[select]") && strings.Contains(stack, "(*scanFlight).run(") {
				return
			}
		}
		if time.Now().After(deadline) {
			t.Fatal("no goroutine parked in scanFlight.run's join-wait select")
		}
		time.Sleep(2 * time.Millisecond)
	}
}

// TestScanFlightJoinsInFlightRun: a second trigger during a slow fn waits on
// the running run and gets the SAME outcome — fn executes exactly once.
func TestScanFlightJoinsInFlightRun(t *testing.T) {
	f := newScanFlight()
	var calls atomic.Int32
	gate := make(chan struct{})
	started := make(chan struct{})
	want := scan.Result{LibraryID: 7, Discovered: 3, Persisted: 2}
	fn := gateFn(gate, started, &calls, want, nil)

	outcome := make(chan scanFlightOutcome, 2)
	launchRun(f, 7, fn, outcome)
	awaitSignal(t, started, "starter entering fn")

	launchRun(f, 7, fn, outcome)
	waitParked(t) // the joiner is provably in the wait path
	close(gate)

	got, err := awaitOutcome(t, outcome, "starter")
	if err != nil {
		t.Fatalf("starter run err = %v, want nil", err)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("starter run result = %+v, want %+v", got, want)
	}
	joinerGot, joinerErr := awaitOutcome(t, outcome, "joiner")
	if joinerErr != nil {
		t.Fatalf("joiner run err = %v, want nil", joinerErr)
	}
	if !reflect.DeepEqual(joinerGot, want) {
		t.Fatalf("joiner run result = %+v, want the running run's %+v", joinerGot, want)
	}
	if n := calls.Load(); n != 1 {
		t.Fatalf("fn executed %d times, want exactly 1 (the joiner must wait, not re-run)", n)
	}
}

// TestScanFlightRecordsOutcomeForLateJoiner: a joiner that waits on a run
// through completion reads the run's RECORDED (result, err) — including the
// error — rather than re-executing fn.
func TestScanFlightRecordsOutcomeForLateJoiner(t *testing.T) {
	f := newScanFlight()
	var calls atomic.Int32
	gate := make(chan struct{})
	started := make(chan struct{})
	wantErr := errors.New("scan aborted")
	want := scan.Result{LibraryID: 3, Discovered: 5}
	fn := gateFn(gate, started, &calls, want, wantErr)

	outcome := make(chan scanFlightOutcome, 2)
	launchRun(f, 3, fn, outcome)
	awaitSignal(t, started, "starter entering fn")

	launchRun(f, 3, fn, outcome)
	waitParked(t) // the late joiner is provably in the wait path
	close(gate)

	// The starter records (want, wantErr) and publishes them; the parked
	// joiner receives the same recorded pair.
	got, err := awaitOutcome(t, outcome, "starter")
	if !errors.Is(err, wantErr) {
		t.Fatalf("starter run err = %v, want %v", err, wantErr)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("starter run result = %+v, want %+v", got, want)
	}
	joinerGot, joinerErr := awaitOutcome(t, outcome, "late joiner")
	if !errors.Is(joinerErr, wantErr) {
		t.Fatalf("late joiner err = %v, want the recorded %v", joinerErr, wantErr)
	}
	if !reflect.DeepEqual(joinerGot, want) {
		t.Fatalf("late joiner result = %+v, want the recorded %+v", joinerGot, want)
	}
	if n := calls.Load(); n != 1 {
		t.Fatalf("fn executed %d times, want exactly 1", n)
	}
}

// TestScanFlightDistinctLibrariesIndependent: two libraries' runs proceed
// concurrently — library 2's scan completes while library 1's is suspended
// mid-fn, and the results never cross.
func TestScanFlightDistinctLibrariesIndependent(t *testing.T) {
	f := newScanFlight()
	var calls atomic.Int32
	gate := make(chan struct{})
	started := make(chan struct{})
	slow := scan.Result{LibraryID: 1, Discovered: 1}
	fn := gateFn(gate, started, &calls, slow, nil)

	outcome := make(chan scanFlightOutcome, 2)
	launchRun(f, 1, fn, outcome)
	awaitSignal(t, started, "library 1 entering fn")

	// Library 2 runs and must complete while library 1 is still parked
	// inside fn.
	other := scan.Result{LibraryID: 2, Discovered: 9}
	launchRun(f, 2, func(context.Context, int64) (scan.Result, error) {
		return other, nil
	}, outcome)

	// Two outcomes total: whichever arrives first must be library 2's (the
	// library 1 run cannot finish — its fn is still blocked on gate).
	first, err := awaitOutcome(t, outcome, "first finishing run")
	if err != nil {
		t.Fatalf("library 2 run err = %v, want nil", err)
	}
	if !reflect.DeepEqual(first, other) {
		t.Fatalf("first finishing run = %+v, want library 2's %+v (library 1 must still be in flight)", first, other)
	}
	close(gate)
	got, err := awaitOutcome(t, outcome, "library 1")
	if err != nil {
		t.Fatalf("library 1 run err = %v, want nil", err)
	}
	if !reflect.DeepEqual(got, slow) {
		t.Fatalf("library 1 run result = %+v, want %+v", got, slow)
	}
	if n := calls.Load(); n != 1 {
		t.Fatalf("library 1 fn executed %d times, want exactly 1", n)
	}
}
